/* Mod "Monsters on the field" (plugin, API 5): PROTOTYPE that shows, over the slot of each of the player's FACE-UP monsters, its art at a
 * larger size (a "hologram" standing on the field). Only the monsters of the starting Water deck for now (the sprites live in sprites/<id>.rgba,
 * generated by tools/mods/mod_monstros.py from the art of a texture pack; nothing from the game goes into the repository).
 * Duel state (map in plugins/src/Cheats/cheats.cpp): slots of 0x14 bytes at 0x09f79d1c + player*0xfac + i*0x14, i = 0..4 monsters: +0 id (&0x1fff),
 * +0x10 bits (0x80 face up, 0x08 defense). Screen position: the field camera is fixed; column c (0..4) of player 0's monster row
 * is centered at x = 313.5 + 46 (c - 2), y = 157.5 (PSP pixels, measured from the cards' quads). A slot only counts if the game really drew
 * a card there this frame (quad_near, API 5): a cut-in or the result screen hides the field and the sprites disappear. */
#include "tfmod.h"
#include <windows.h>
#include <map>
#include <string>
#include <vector>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <algorithm>

static const TfModApi *A;
static const float OPP_X0 = 313.5f, OPP_DX = 44.f, OPP_Y = 110.f, MINI_W = 44.f, MINI_H = 52.f;
static const uint32_t F_QUADRO = 0x08833fc4, CASAS = 0x09f79d1c, PASSO = 0xfac;
struct Img { int w = 0, h = 0; std::vector<uint32_t> px; };
static std::map<uint32_t, Img> g_img;   /* id da carta -> sprite */
static int g_on = 0, g_escala = 100;     /* experimental: desligado por padrao; tamanho em % */

static std::wstring cfg_path(void) { return std::wstring(A->mod_dir) + L"/config.ini"; }
static void cfg_save(void) { if (FILE *f = _wfopen(cfg_path().c_str(), L"w")) { fprintf(f, "enabled=%d\nscale=%d\n", g_on, g_escala); fclose(f); } }
static void cfg_load(void) {
    if (FILE *f = _wfopen(cfg_path().c_str(), L"r")) { char l[64]; int v; while (fgets(l, sizeof l, f)) { if (sscanf(l, "enabled=%d", &v) == 1 || sscanf(l, "ligado=%d", &v) == 1) g_on = v != 0; else if (sscanf(l, "scale=%d", &v) == 1 || sscanf(l, "escala=%d", &v) == 1) g_escala = std::max(50, std::min(200, v)); } fclose(f); }
    if (const char *e = getenv("TF_MONS_ESCALA")) g_escala = std::max(50, std::min(200, atoi(e)));   /* testes */
    if (const char *e = getenv("TF_MONS_OFF")) g_on = atoi(e) == 0;
}
static int on_get(void) { return g_on; }
static void on_set(int v) { g_on = v != 0; cfg_save(); }
static int esc_get(void) { return g_escala; }
static void esc_set(int v) { g_escala = std::max(50, std::min(200, v)); cfg_save(); }

static void carregar_sprites(void) {
    const std::wstring dir = std::wstring(A->mod_dir) + L"/sprites/*.rgba";
    WIN32_FIND_DATAW fd; HANDLE h = FindFirstFileW(dir.c_str(), &fd);
    if (h == INVALID_HANDLE_VALUE) return;
    do {
        const uint32_t id = (uint32_t)wcstoul(fd.cFileName, nullptr, 10);
        if (FILE *f = _wfopen((std::wstring(A->mod_dir) + L"/sprites/" + fd.cFileName).c_str(), L"rb")) {
            uint32_t wh[2];
            if (fread(wh, 4, 2, f) == 2 && wh[0] && wh[1] && wh[0] <= 2048 && wh[1] <= 2048) {
                Img im; im.w = (int)wh[0]; im.h = (int)wh[1]; im.px.resize((size_t)im.w * im.h);
                if (fread(im.px.data(), 4, im.px.size(), f) == im.px.size()) g_img[id] = std::move(im);
            }
            fclose(f);
        }
    } while (FindNextFileW(h, &fd));
    FindClose(h);
}

/* The overlay sits above the whole game picture, so a sprite cannot go "behind" what the game draws later. API 8 tells which 2D pieces the game drew after
 * the field cards: if a big one (a window, a card preview) overlaps a good part of the sprite, the sprite is simply not shown that frame. */
static bool covered(float x0, float y0, float x1, float y1) {
    if (A->version < 8) return false;
    float r[32 * 4]; const int n = std::min(32, A->occluders(x0, y0, x1, y1, r, 32));
    const float area = (x1 - x0) * (y1 - y0);
    for (int i = 0; i < n; i++) {
        const float *o = r + i * 4, w = o[2] - o[0], h = o[3] - o[1];
        if (w < 40 || h < 30) continue;   /* text, cursors, thin bars: ignore */
        const float ox = std::min(x1, o[2]) - std::max(x0, o[0]), oy = std::min(y1, o[3]) - std::max(y0, o[1]);
        if (ox > 0 && oy > 0 && ox * oy >= 0.15f * area) return true;
    }
    return false;
}

static int hk_quadro(TfCpu *) {
    if (!g_on || !A->module_loaded("libduel_eng")) return 0;
    for (int pl = 0; pl < 2; pl++) for (int col = 0; col < 5; col++) {
        const uint32_t casa = CASAS + pl * PASSO + col * 0x14;
        const uint32_t id = *(uint32_t *)A->mem(casa) & 0x1fff, bits = *(uint32_t *)A->mem(casa + 0x10);
        auto it = g_img.find(id);
        if (it == g_img.end() || !(bits & 0x80)) continue;
        /* player: row at y 157.5, 46 px apart; opponent: farther row (perspective), mirrored, a bit tighter (measured in a duel) */
        const float cx = pl ? OPP_X0 - OPP_DX * (col - 2) : 313.5f + 46.f * (col - 2), cy = pl ? OPP_Y : 157.5f;
        if (!A->quad_near((int)cx, (int)cy, 10, 12, 44)) continue;   /* a carta nao esta desenhada ali agora (cut-in, resultado...) */
        const bool defesa = (bits & 0x08) != 0;
        /* miniature: fits a small box (wider monsters are limited by width, taller ones by height) */
        const Img &im = it->second; const float k = g_escala / 100.f * (defesa ? 0.8f : 1.f) * (pl ? 0.85f : 1.f);
        const float asp = (float)im.h / im.w, dw = std::min(MINI_W, MINI_H / asp) * k, dh = dw * asp;
        const uint8_t alfa = defesa ? 200 : 255; const float x = cx - dw / 2, y = cy + 8.f - dh;
        if (covered(x, y, x + dw, y + dh)) continue;   /* a game window (phase select, card preview, menu...) is on top of the field: stand aside */
        A->sprite(100 + pl * 5 + col, im.px.data(), im.w, im.h, x, y, dw, dh, alfa);
    }
    return 0;
}

extern "C" __declspec(dllexport) int tfmod_init(const TfModApi *api) {
    A = api;
    if (A->version < 5) { A->log("Monstros no campo precisa da API 5 (runtime mais novo)"); return 1; }
    cfg_load(); carregar_sprites();
    A->add_toggle(L"&Monsters on the field (experimental)", 0, on_get, on_set);
    A->add_slider(L"Size of the monsters on the field", L"%", 50, 200, 100, esc_get, esc_set);
    A->hook(F_QUADRO, hk_quadro);
    A->log("Monstros no campo: %zu sprite(s), %s", g_img.size(), g_on ? "ligado" : "desligado");
    return 0;
}
